import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class BasePeriod_toDurationTo_TriageGen2Test {

    @Test
    public void testToDurationTo_StandardPeriod() {
        // Create a period of 1 day (24 hours)
        // BasePeriod is protected, so we use Period which extends BasePeriod
        Period period = new Period(1, 0, 0, 1, 0, 0, 0, 0, PeriodType.dayBased);

        Instant endInstant = new Instant(1000000L);

        // The method calculates: startMillis = chrono.add(this, endMillis, -1)
        // Since this is a day-based period, it should subtract 1 day from endInstant
        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        // Expected duration is the length of the period in millis
        // 1 day = 86400000 ms
        assertEquals(86400000L, result.getMillis());
        assertEquals(endInstant.getMillis(), result.getEndMillis());
    }

    @Test
    public void testToDurationTo_MillisPeriod() {
        // Create a period of 500 millis
        Period period = new Period(0, 0, 0, 0, 0, 0, 0, 500, PeriodType.millisBased);

        Instant endInstant = new Instant(2000000L);

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(500L, result.getMillis());
        assertEquals(2000000L, result.getEndMillis());
        assertEquals(1500000L, result.getStartMillis());
    }

    @Test
    public void testToDurationTo_ComplexPeriod() {
        // Create a period of 1 hour and 30 minutes
        Period period = new Period(0, 0, 0, 0, 1, 30, 0, 0, PeriodType.standard);

        DateTime endDateTime = DateTime.parse("2023-01-01T12:00:00.000Z", DateTimeFormat.dateTime());
        ReadableInstant endInstant = endDateTime.toInstant();

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        // 1 hour 30 mins = 3600 + 1800 = 5400 seconds = 5400000 ms
        assertEquals(5400000L, result.getMillis());
        assertEquals(endInstant.getMillis(), result.getEndMillis());
    }

    @Test
    public void testToDurationTo_ZeroPeriod() {
        Period period = new Period(0, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard);
        Instant endInstant = new Instant(5000L);

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        assertEquals(0L, result.getMillis());
        assertEquals(5000L, result.getEndMillis());
        assertEquals(5000L, result.getStartMillis());
    }

    @Test
    public void testToDurationTo_LargeValues() {
        // Test with a very large number of days to ensure no overflow in millis calculation before duration creation
        // Note: Joda Duration handles long, but the period subtraction happens via Chronology
        Period period = new Period(10, 0, 0, 0, 0, 0, 0, 0, PeriodType.dayBased);
        Instant endInstant = new Instant(Long.MAX_VALUE - 100000000L); 

        Duration result = period.toDurationTo(endInstant);

        assertNotNull(result);
        // 10 days = 10 * 24 * 60 * 60 * 1000 = 864,000,000 ms
        assertEquals(864000000L, result.getMillis());
    }
}
